/* 
* InheritableThreadLocal values pertaining to this thread. This map is 
* maintained by the InheritableThreadLocal class. 
*/ 
ThreadLocal . ThreadLocalMap inheritableThreadLocals = null ; 
// 其他代码省略... 
}

static class ThreadLocalMap { 
static class Entry extends WeakReference > { 
Object value ; 
Entry ( ThreadLocal k , Object v ) { 
super ( k ); 
value = v ; 
} 
} 
// 保存threadlocal变量的key、value 
private Entry [] table ; 
}

线程变量的清除 
由于jrasp的基本特征是热卸载（加载），如果不能清除线程变量，将会导致已经加载的 jrasp-agent/module 无法正常卸载，造成比较严重的内存泄漏。     因此，jrasp-agent 在卸载时, 执行 强制清除 线程变量操作，彻底解决内存泄漏问题； 
// 除去 context 线程变量 List threadList = ThreadUtil.getThreadList(); for (Thread thread : threadList) { /** * 在 rasp 退出时清理线程变量，这里使用 inheritableThreadLocals 应该清除 inheritableThreadLocals * @see Thread.inheritableThreadLocals * @see Thread.threadLocals */      Object threadLocalMap = RaspReflectUtils.unCaughtGetClassDeclaredJavaFieldValue(Thread.class,  "inheritableThreadLocals" , thread);       if ( null != threadLocalMap) { // 反射获取 ThreadLocalMap类的 remove 方法 Method method = RaspReflectUtils.unCaughtGetClassDeclaredJavaMethod(threadLocalMap.getClass(), "remove" , ThreadLocal.class); try {              RaspReflectUtils.unCaughtInvokeMethod(method, threadLocalMap, requestContext);                                                  } catch ( Exception e) { e.printStackTrace(); } } }

