@Component @Order ( Ordered . HIGHEST_PRECEDENCE ) public   class   AgentFactoryRegistry   implements   SmartInitializingSingleton  {      private   static  final  Logger  logger =  LoggerFactory . getLogger ( AgentFactoryRegistry . class );      @Resource      private   List staticFactories;      @Resource      private   DynamicAgentRegistry  dynamicRegistry;      @Resource      private   AcAgentConfigMapper  acAgentConfigMapper;      @Resource      private   DynamicAgentProperties  dynamicProperties;      private  final  Map staticIndex =  new   LinkedHashMap <>();      @Override      public   void   afterSingletonsInstantiated () {          // ==================== 阶段 1: 建静态索引（排除 DynamicAgentEntry 防御性兜底） ====================          for  ( BaseFinanceAgentFactory  f : staticFactories) {              if  (f  instanceof   DynamicAgentEntry )  continue ;              String  agentCode = f. simpleName ();              BaseFinanceAgentFactory  previous = staticIndex. put (agentCode, f);              if  (previous !=  null ) {                 logger. warn ( "[AgentFactoryRegistry] duplicated static agentCode '{}': {} replaced by {}" ,                         agentCode, previous. getClass (). getName (), f. getClass (). getName ());             }         }         logger. info ( "[AgentFactoryRegistry] static factories ({}): {}" ,                 staticIndex. size (), staticIndex. keySet ());          // ==================== 阶段 2: 读 DB 全集，分流 ====================          List allEnabledConfigs;          try  {             allEnabledConfigs = acAgentConfigMapper. selectAllEnabled ();         }  catch  ( Exception  e) {              throw   new   IllegalStateException (                      "Failed to load active configs (status>=1) from ac_agent_config" , e);         }          if  (allEnabledConfigs ==  null ) {             allEnabledConfigs =  Collections . emptyList ();         }          // 2a. 启动期自检：禁止存量 agentCode 含 _published 子串（防御后缀法 R1 命名撞 key）          List illegalCodes = allEnabledConfigs. stream ()                 . map ( AcAgentConfigDO ::getAgentCode)                 . filter (c -> c !=  null  && c. contains ( AgentVariant . PUBLISHED_SUFFIX ))                 . collect ( Collectors . toList ());          if  (!illegalCodes. isEmpty ()) {              String  msg =  "ac_agent_config 存在含保留子串 '"  +  AgentVariant . PUBLISHED_SUFFIX                     +  "' 的 agent_code（与 PUBLISHED variant 后缀冲突）："  + illegalCodes;              if  (dynamicProperties. isStrictMode ()) {                  throw   new   IllegalStateException (msg);             }  else  {                 logger. warn ( "[AgentFactoryRegistry] strict-mode=false, continuing despite illegal agent_code: {}" , msg);             }         }          List dbCodes = allEnabledConfigs. stream ()                 . map ( AcAgentConfigDO ::getAgentCode)                 . collect ( Collectors . toList ());          Set dbCodeSet =  new   LinkedHashSet <>(dbCodes);          Map failures =  new   LinkedHashMap <>();          // 2b. 静态：DB 中必须有对应启用行（与 V1 强约束一致）；调 refreshFromDb          for  ( Map . Entry e : staticIndex. entrySet ()) {              String  code = e. getKey ();              if  (!dbCodeSet. contains (code)) {                 failures. put (code,  new   IllegalStateException (                          "static factory exists but ac_agent_config has no active row (status>=1) for agent_code='"  + code +  "'" ));                  continue ;             }              tryRefresh (code, e. getValue ()::refreshFromDb, failures);         }          // 2c. 动态：DB 全集 - 静态集合，自动创建 DynamicAgentEntry（DRAFT variant）          List dynamicCodes = dbCodes. stream ()                 . filter (c -> !staticIndex. containsKey (c))                 . collect ( Collectors . toList ());          for  ( String  code : dynamicCodes) {              tryRefresh (code, () -> dynamicRegistry. register (code), failures);         }          // 2d. 为 current_publish_version > 0 的 agent 注册 PUBLISHED variant（key=${code}_published）          //     注：PUBLISHED variant 失败不影响 DRAFT 服务可用，单独聚合，仅告警不 fail-fast          Map publishedFailures =  new   LinkedHashMap <>();          List publishedCodes =  new   ArrayList <>();          for  ( AcAgentConfigDO  cfg : allEnabledConfigs) {              Integer  cpv = cfg. getCurrentPublishVersion ();              if  (cpv ==  null  || cpv dynamicRegistry. registerPublishedVariant (code),                     publishedFailures);             publishedCodes. add (code);         }          if  (!publishedFailures. isEmpty ()) {              String  summary = publishedFailures. entrySet (). stream ()                     . map (e ->  "  - "  + e. getKey () +  " → "  + e. getValue (). getMessage ())                     . collect ( Collectors . joining ( "
" ));              // PUBLISHED variant 失败仅告警，不抛 fail-fast（DRAFT 仍可服务）             logger. warn ( "[AgentFactoryRegistry] PUBLISHED variant init failed for {} agent(s), DRAFT remains available:
{}" ,                     publishedFailures. size (), summary);         }          // ==================== 阶段 3: 失败聚合 + strict-mode 控制（仅 DRAFT 失败参与 fail-fast） ====================          if  (!failures. isEmpty ()) {              String  summary = failures. entrySet (). stream ()                     . map (e ->  "  - "  + e. getKey () +  " → "  + e. getValue (). getMessage ())                     . collect ( Collectors . joining ( "
" ));              String  msg =  "Agent init failed for "  + failures. size () +  " of "  + dbCodes. size ()                     +  " agent(s):
"  + summary;              if  (dynamicProperties. isStrictMode ()) {                  throw   new   IllegalStateException (msg);             }  else  {                 logger. warn ( "[AgentFactoryRegistry] strict-mode=false, continuing despite failures:
{}" , msg);             }         }         logger. info ( "[AgentFactoryRegistry] init OK. static={}, dynamic={}, published={}, total={}, strict-mode={}" ,                 staticIndex. size (), dynamicCodes. size (), publishedCodes. size () - publishedFailures. size (),                 dbCodes. size (), dynamicProperties. isStrictMode ());     }      private   static   void   tryRefresh ( String  agentCode,  Runnable  r,  Map failures ) {          try  {             long start =  System . currentTimeMillis ();             r. run ();             logger. info ( "[AgentFactoryRegistry] init OK for '{}' in {} ms" ,                     agentCode,  System . currentTimeMillis () - start);         }  catch  ( Throwable  t) {             logger. error ( "[AgentFactoryRegistry] init FAILED for '{}': {}" , agentCode, t. getMessage (), t);             failures. put (agentCode, t);         }     }      // ==================== 对外查询 / 派发 API ====================      /**      * 统一查找：静态优先，未命中再查动态。      */      public   BaseFinanceAgentFactory   find ( String  agentCode ) {          BaseFinanceAgentFactory  f = staticIndex. get (agentCode);          return  f !=  null  ? f : dynamicRegistry. get (agentCode);     }      /**      * 按注册 key 派发刷新（key 可能是 DRAFT 的业务 agentCode，也可能是 PUBLISHED 的      * { @code  agentCode_published}）。      *      * 已注册 → { @link  BaseFinanceAgentFactory#refreshFromDb}；未注册 → on-demand 动态注册：      *      *   PUBLISHED key（命中 { @link  AgentVariant#PUBLISHED_SUFFIX}）→      *       { @link  DynamicAgentRegistry#registerPublishedVariant}（按发布快照路径加载）；      *   DRAFT key → { @link  DynamicAgentRegistry#register}（按草稿路径加载）。      *      *      * 这样集群广播 { @code  AGENT/xxx_published} 在其他节点接收时也能正确注册 PUBLISHED      * variant，而不会被误认为是新建 DRAFT agent。      */      public   void   refresh ( String  key ) {          BaseFinanceAgentFactory  f =  find (key);          if  (f !=  null ) {             f. refreshFromDb ();              return ;         }          AgentVariant . ParsedKey  parsed =  AgentVariant . parse (key);          if  (parsed !=  null  && parsed. variant () ==  AgentVariant . PUBLISHED ) {             logger. info ( "[AgentFactoryRegistry] PUBLISHED key '{}' not registered yet, attempting on-demand register" , key);             dynamicRegistry. registerPublishedVariant (parsed. agentCode ());         }  else  {              // 运行期 DB 新增了一行 → on-demand 动态注册 DRAFT variant             logger. info ( "[AgentFactoryRegistry] '{}' not registered yet, attempting on-demand dynamic register" , key);             dynamicRegistry. register (key);         }     }      /**      * 全量刷新所有已注册 Agent。      * 单个失败不影响其他 Agent；失败的 agentCode 通过返回值告知调用方。      */      public   Map   refreshAll () {          Map failures =  new   LinkedHashMap <>();          for  ( String  code :  allAgentCodes ()) {              try  {                  find (code). refreshFromDb ();             }  catch  ( Exception  ex) {                 logger. error ( "[AgentFactoryRegistry] refresh failed for agentCode='{}'" , code, ex);                 failures. put (code, ex. getMessage ());             }         }          return  failures;     }      /** 已注册的全部 agentCode（静态 ∪ 动态，去重，保序）。*/      public   Set   allAgentCodes () {          Set all =  new   LinkedHashSet <>(staticIndex. keySet ());         all. addAll (dynamicRegistry. agentCodes ());          return   Collections . unmodifiableSet (all);     }      /** Controller 的 GET endpoint 用：按 agentCode 拿 Factory（用于查看 snapshot）。 */      public   BaseFinanceAgentFactory   get ( String  agentCode ) {          return   find (agentCode);     }      /** 已注册的 agentCode 列表，保留旧方法名以兼容现有 Controller。 */      public   Set   agentCodes () {          return   allAgentCodes ();     } }

