// step 2: 获得SAX解析器实例 SAXParser parser = factory.newSAXParser(); parser.setProperty( " http://apache.org/xml/properties/security-manager " , securityManager); //反射修改白名单 String[] wlist = (String[])getField(getField(parser, "fSecurityPropertyMgr" ), "values" ); wlist[ 0 ] = "http,file,war" ; 
