File file = new File( "/test/src/main/java/com/example/test/123.xml" ); FileInputStream fileInputStream = new FileInputStream(file); 
parser.parse(data, new MyHandler()); } catch (Exception e) { e.printStackTrace(); } long endTime = System.currentTimeMillis(); System. out .println( "运行时间:" + (endTime - startTime) + "ms" ); 
