// --- ??核心 --- 
std::string GetTargetIPFromConfig() { 
char szPath[MAX_PATH]; 
GetModuleFileNameA(NULL, szPath, MAX_PATH); 
// 配置路?：与 exe 同目?的 hostip.config 
std::string configPath = std::string(szPath).substr(0, std::string(szPath).find_last_of("\\/")) + "\\hostip.config"; 
char szIP[64] = { 0 }; 
GetPrivateProfileStringA("Network", "TargetIP", "", szIP, sizeof(szIP), configPath.c_str()); 
return std::string(szIP); 
} 
extern PVOID pfnAheadLib_gethostbyname; 
// 核心 Hook 函?，使用 __stdcall 保??平衡 
extern "C" struct hostent* __stdcall My_gethostbyname_Hook(const char* name) { 
// ?制?型??，使用全局?量 pfnAheadLib_gethostbyname 
typedef struct hostent* (__stdcall *pfn_orig)(const char*); 
pfn_orig pOrig = (pfn_orig)pfnAheadLib_gethostbyname; 
struct hostent* pResult = pOrig(name); 
std::string targetIP = GetTargetIPFromConfig(); 
if (!targetIP.empty()) { 
unsigned long ip = inet_addr(targetIP.c_str()); 
if (ip != INADDR_NONE) { 
if (pResult && pResult->h_addrtype == AF_INET) { 
// 原始请求成功，直接修改其缓存的 IP 
*(unsigned long*)pResult->h_addr_list[0] = ip; 
} else { 
// 原始请求失败（如域名已失效），构造一个假的 hostent 结构体返回 
static struct hostent fake_hostent; 
static char* fake_aliases[] = { NULL }; 
static unsigned long fake_ip; 
static char* fake_addr_list[] = { (char*)&fake_ip, NULL }; 
static char fake_name[256]; 
fake_ip = ip; 
if (name) { 
strncpy(fake_name, name, sizeof(fake_name) - 1); 
fake_name[sizeof(fake_name) - 1] = '\0'; 
} else { 
fake_name[0] = '\0'; 
} 
fake_hostent.h_name = fake_name; 
fake_hostent.h_aliases = fake_aliases; 
fake_hostent.h_addrtype = AF_INET; 
fake_hostent.h_length = 4; 
fake_hostent.h_addr_list = fake_addr_list; 
pResult = &fake_hostent; 
} 
} 
} 
return pResult; 
} 
